/*!
 * dashboard/js/chart.min.js
 * MiniChart — small Chart.js-like subset (line + bar) for internal dashboards.
 * API: new Chart(ctxOrCanvas, { type, data:{labels,datasets}, options })
 * Methods: update(), destroy()
 *
 * If you later replace this file with the official Chart.js build, your code will still work.
 */
(function (global) {
  "use strict";

  // -------------------------
  // Helpers
  // -------------------------
  function isCanvas(el) {
    return el && el.nodeType === 1 && el.tagName && el.tagName.toLowerCase() === "canvas";
  }

  function getCanvasAndCtx(input) {
    if (!input) return { canvas: null, ctx: null };
    if (isCanvas(input)) {
      return { canvas: input, ctx: input.getContext("2d") };
    }
    // Accept 2D context
    if (input.canvas && input.fillRect) {
      return { canvas: input.canvas, ctx: input };
    }
    // Accept selector string
    if (typeof input === "string") {
      var el = document.querySelector(input);
      if (isCanvas(el)) return { canvas: el, ctx: el.getContext("2d") };
    }
    return { canvas: null, ctx: null };
  }

  function clamp(n, a, b) {
    return Math.max(a, Math.min(b, n));
  }

  function toNumber(v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  }

  function maxOf(arr) {
    var m = -Infinity;
    for (var i = 0; i < arr.length; i++) m = Math.max(m, toNumber(arr[i]));
    return m === -Infinity ? 0 : m;
  }

  function minOf(arr) {
    var m = Infinity;
    for (var i = 0; i < arr.length; i++) m = Math.min(m, toNumber(arr[i]));
    return m === Infinity ? 0 : m;
  }

  function pick(obj, path, fallback) {
    try {
      var parts = path.split(".");
      var cur = obj;
      for (var i = 0; i < parts.length; i++) {
        if (!cur) return fallback;
        cur = cur[parts[i]];
      }
      return cur === undefined ? fallback : cur;
    } catch (e) {
      return fallback;
    }
  }

  function font(ctx, size, weight) {
    ctx.font = (weight || 600) + " " + (size || 12) + "px system-ui, -apple-system, Segoe UI, Roboto, Arial";
  }

  function niceMax(v) {
    // make axis max "pretty"
    if (v <= 0) return 1;
    var exp = Math.floor(Math.log10(v));
    var f = v / Math.pow(10, exp);
    var nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10;
    return nf * Math.pow(10, exp);
  }

  function formatNumber(v, locale) {
    try {
      return new Intl.NumberFormat(locale || undefined).format(v);
    } catch (e) {
      return String(v);
    }
  }

  // -------------------------
  // Tooltip (DOM)
  // -------------------------
  function Tooltip(canvas) {
    this.canvas = canvas;
    this.el = document.createElement("div");
    this.el.style.position = "absolute";
    this.el.style.pointerEvents = "none";
    this.el.style.zIndex = "50";
    this.el.style.padding = "6px 8px";
    this.el.style.borderRadius = "10px";
    this.el.style.border = "1px solid rgba(0,0,0,.12)";
    this.el.style.boxShadow = "0 10px 25px rgba(0,0,0,.10)";
    this.el.style.background = "rgba(255,255,255,.96)";
    this.el.style.font = "600 12px system-ui, -apple-system, Segoe UI, Roboto, Arial";
    this.el.style.whiteSpace = "nowrap";
    this.el.style.display = "none";
    document.body.appendChild(this.el);
  }
  Tooltip.prototype.show = function (x, y, html) {
    this.el.innerHTML = html;
    this.el.style.left = x + "px";
    this.el.style.top = y + "px";
    this.el.style.display = "block";
  };
  Tooltip.prototype.hide = function () {
    this.el.style.display = "none";
  };
  Tooltip.prototype.destroy = function () {
    if (this.el && this.el.parentNode) this.el.parentNode.removeChild(this.el);
  };

  // -------------------------
  // Chart class
  // -------------------------
  function Chart(input, config) {
    var res = getCanvasAndCtx(input);
    this.canvas = res.canvas;
    this.ctx = res.ctx;
    this.config = config || {};
    this._destroyed = false;

    if (!this.canvas || !this.ctx) {
      // no-op instance
      return;
    }

    this._dpr = Math.max(1, global.devicePixelRatio || 1);
    this._padding = { top: 18, right: 16, bottom: 34, left: 44 };
    this._points = []; // computed points for tooltip
    this._tooltip = new Tooltip(this.canvas);

    this._onMouseMove = this._handleMouseMove.bind(this);
    this._onMouseLeave = this._handleMouseLeave.bind(this);
    this._onResize = this._handleResize.bind(this);

    this.canvas.addEventListener("mousemove", this._onMouseMove);
    this.canvas.addEventListener("mouseleave", this._onMouseLeave);
    global.addEventListener("resize", this._onResize);

    this.update();
  }

  Chart.prototype.destroy = function () {
    if (this._destroyed) return;
    this._destroyed = true;

    try {
      if (this.canvas) {
        this.canvas.removeEventListener("mousemove", this._onMouseMove);
        this.canvas.removeEventListener("mouseleave", this._onMouseLeave);
      }
      global.removeEventListener("resize", this._onResize);
      if (this._tooltip) this._tooltip.destroy();
    } catch (e) {}
  };

  Chart.prototype.update = function () {
    if (this._destroyed || !this.canvas || !this.ctx) return;

    this._resizeToContainer();
    this._render();
  };

  Chart.prototype._resizeToContainer = function () {
    var canvas = this.canvas;
    var dpr = this._dpr;

    var cssW = canvas.clientWidth || 600;
    var cssH = canvas.clientHeight || 280;

    // Default height if not explicitly constrained
    if (!canvas.style.height && (!canvas.clientHeight || canvas.clientHeight < 80)) {
      cssH = 280;
    }

    var w = Math.round(cssW * dpr);
    var h = Math.round(cssH * dpr);

    if (canvas.width !== w) canvas.width = w;
    if (canvas.height !== h) canvas.height = h;
  };

  Chart.prototype._handleResize = function () {
    if (this._destroyed) return;
    this.update();
  };

  Chart.prototype._handleMouseLeave = function () {
    if (this._tooltip) this._tooltip.hide();
  };

  Chart.prototype._handleMouseMove = function (evt) {
    if (!this._points || !this._points.length) return;

    var rect = this.canvas.getBoundingClientRect();
    var mx = evt.clientX - rect.left;
    var my = evt.clientY - rect.top;

    // Find nearest point
    var best = null;
    var bestDist = Infinity;
    for (var i = 0; i < this._points.length; i++) {
      var p = this._points[i];
      var dx = mx - p.cx;
      var dy = my - p.cy;
      var d = dx * dx + dy * dy;
      if (d < bestDist) {
        bestDist = d;
        best = p;
      }
    }

    if (!best || bestDist > 900) { // threshold
      this._tooltip.hide();
      return;
    }

    var html =
      "<span style='opacity:.75;margin-right:6px;'>" + (best.label || "") + "</span>" +
      "<span>" + formatNumber(best.value, pick(this.config, "options.locale", undefined)) + "</span>";

    this._tooltip.show(evt.clientX + 12, evt.clientY + 12, html);
  };

  Chart.prototype._render = function () {
    var ctx = this.ctx;
    var canvas = this.canvas;
    var dpr = this._dpr;

    // scale drawing coords (we draw in CSS pixels)
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    var W = canvas.width / dpr;
    var H = canvas.height / dpr;

    ctx.clearRect(0, 0, W, H);

    var type = (this.config.type || "line").toLowerCase();
    var labels = pick(this.config, "data.labels", []) || [];
    var datasets = pick(this.config, "data.datasets", []) || [];

    // Options
    var showLegend = !!pick(this.config, "options.plugins.legend.display", true);
    var beginAtZero = !!pick(this.config, "options.scales.y.beginAtZero", true);
    var locale = pick(this.config, "options.locale", undefined);
    var grid = pick(this.config, "options.grid", true) !== false;

    // Flatten values to compute y range
    var all = [];
    for (var di = 0; di < datasets.length; di++) {
      var dataArr = datasets[di] && datasets[di].data ? datasets[di].data : [];
      for (var j = 0; j < dataArr.length; j++) all.push(toNumber(dataArr[j]));
    }

    var yMin = minOf(all);
    var yMax = maxOf(all);
    if (beginAtZero) yMin = Math.min(0, yMin);

    var yTop = niceMax(yMax <= yMin ? yMin + 1 : yMax);
    var yBottom = yMin;

    if (yTop === yBottom) yTop = yBottom + 1;

    var pad = this._padding;
    var x0 = pad.left;
    var y0 = pad.top;
    var x1 = W - pad.right;
    var y1 = H - pad.bottom;

    // Axes
    ctx.save();
    ctx.strokeStyle = "rgba(15,23,42,.12)";
    ctx.lineWidth = 1;

    // Y axis
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x0, y1);
    ctx.stroke();

    // X axis
    ctx.beginPath();
    ctx.moveTo(x0, y1);
    ctx.lineTo(x1, y1);
    ctx.stroke();
    ctx.restore();

    // Grid + y ticks
    var ticks = 5;
    ctx.save();
    ctx.fillStyle = "rgba(15,23,42,.65)";
    ctx.strokeStyle = "rgba(15,23,42,.08)";
    ctx.lineWidth = 1;
    font(ctx, 11, 700);

    for (var t = 0; t <= ticks; t++) {
      var yy = y1 - (t / ticks) * (y1 - y0);
      var val = yBottom + (t / ticks) * (yTop - yBottom);

      if (grid) {
        ctx.beginPath();
        ctx.moveTo(x0, yy);
        ctx.lineTo(x1, yy);
        ctx.stroke();
      }

      var txt = formatNumber(Math.round(val), locale);
      ctx.fillText(txt, 6, yy + 4);
    }
    ctx.restore();

    // X labels
    ctx.save();
    ctx.fillStyle = "rgba(15,23,42,.65)";
    font(ctx, 11, 700);
    var n = Math.max(1, labels.length);
    var stepX = (x1 - x0) / Math.max(1, n - 1);
    var labelEvery = 1;
    if (n > 20) labelEvery = 4;
    else if (n > 12) labelEvery = 2;

    for (var li = 0; li < labels.length; li++) {
      if (li % labelEvery !== 0 && li !== labels.length - 1) continue;
      var lx = x0 + li * stepX;
      var lab = String(labels[li]);
      var tw = ctx.measureText(lab).width;
      ctx.fillText(lab, clamp(lx - tw / 2, x0, x1 - tw), y1 + 22);
    }
    ctx.restore();

    // Legend
    var legendH = 0;
    if (showLegend && datasets.length) {
      ctx.save();
      font(ctx, 12, 800);
      ctx.fillStyle = "rgba(15,23,42,.85)";
      var lx2 = x0;
      var ly2 = 8;
      for (var ldi = 0; ldi < datasets.length; ldi++) {
        var ds = datasets[ldi] || {};
        var name = ds.label ? String(ds.label) : "Dataset " + (ldi + 1);
        var bc = ds.borderColor || "rgba(37,99,235,.9)";
        ctx.fillStyle = bc;
        ctx.fillRect(lx2, ly2, 12, 12);
        ctx.fillStyle = "rgba(15,23,42,.85)";
        ctx.fillText(name, lx2 + 18, ly2 + 11);
        lx2 += 18 + ctx.measureText(name).width + 16;
        legendH = Math.max(legendH, 18);
      }
      ctx.restore();
    }

    // Compute points for tooltip
    this._points = [];

    // Draw datasets
    for (var k = 0; k < datasets.length; k++) {
      var ds2 = datasets[k] || {};
      var arr2 = ds2.data || [];
      var border = ds2.borderColor || "rgba(37,99,235,.9)";
      var fill = ds2.backgroundColor || "rgba(37,99,235,.12)";
      var width = toNumber(ds2.borderWidth || 2);

      if (type === "bar") {
        // bars
        var barCount = datasets.length;
        var groupW = (x1 - x0) / n;
        var barW = Math.max(4, (groupW * 0.72) / barCount);

        for (var bi = 0; bi < n; bi++) {
          var v2 = toNumber(arr2[bi]);
          var xCenter = x0 + bi * groupW + groupW / 2;
          var xLeft = xCenter - (barCount * barW) / 2 + k * barW;
          var yVal = y1 - ((v2 - yBottom) / (yTop - yBottom)) * (y1 - y0);
          yVal = clamp(yVal, y0, y1);

          ctx.save();
          ctx.fillStyle = fill;
          ctx.strokeStyle = border;
          ctx.lineWidth = 1;

          var hBar = y1 - yVal;
          ctx.beginPath();
          ctx.rect(xLeft, yVal, barW - 2, hBar);
          ctx.fill();
          ctx.restore();

          this._points.push({
            cx: xLeft + barW / 2,
            cy: yVal,
            value: v2,
            label: labels[bi] != null ? String(labels[bi]) : ""
          });
        }
      } else {
        // line
        ctx.save();
        ctx.strokeStyle = border;
        ctx.lineWidth = width;
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        ctx.beginPath();
        for (var pi = 0; pi < n; pi++) {
          var v3 = toNumber(arr2[pi]);
          var x = x0 + pi * stepX;
          var y = y1 - ((v3 - yBottom) / (yTop - yBottom)) * (y1 - y0);
          y = clamp(y, y0, y1);
          if (pi === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);

          this._points.push({
            cx: x,
            cy: y,
            value: v3,
            label: labels[pi] != null ? String(labels[pi]) : ""
          });
        }
        ctx.stroke();

        // points
        ctx.fillStyle = "#ffffff";
        ctx.strokeStyle = border;
        ctx.lineWidth = 2;

        for (var pp = 0; pp < n; pp++) {
          var vv = toNumber(arr2[pp]);
          var xx = x0 + pp * stepX;
          var yy2 = y1 - ((vv - yBottom) / (yTop - yBottom)) * (y1 - y0);
          yy2 = clamp(yy2, y0, y1);
          ctx.beginPath();
          ctx.arc(xx, yy2, 3.2, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
        ctx.restore();
      }
    }
  };

  // Expose global Chart
  global.Chart = Chart;
})(window);
